"""
    PipelineTemplateOptions

Options for [`generate_pipeline_template`](@ref) (`num_steps`, `subsections_per_step`, `include_usage_example`, `include_setup`, `include_summary`).
"""
@kwdef struct PipelineTemplateOptions
    num_steps::Int = 5
    subsections_per_step::Int = 2
    include_usage_example::Bool = true
    include_setup::Bool = true
    include_summary::Bool = true
end

function _write_pipeline_template(io::IO, function_name::String, options::PipelineTemplateOptions)
    write(
        io,
        """
        # Custom EEG Preprocessing Pipeline Template
        # Generated by EegFun.generate_pipeline_template()

        using EegFun
        using TOML
        \"\"\"
            $function_name(config::String; base_dir::Union{String,Nothing} = nothing, log_level::Symbol = :info)

        Custom preprocessing pipeline for EEG data.
        \"\"\"
        function $function_name(config::String; base_dir::Union{String,Nothing} = nothing, log_level::Symbol = :info)
            isnothing(base_dir) && (base_dir = abspath(dirname(abspath(config))))

            global_log = EegFun.setup_global_logging("$function_name.log"; log_level = log_level)

            output_directory = ""
            raw_data_files = String[]
            processed_files = 0
            failed_files = String[]
            all_epoch_counts = EegFun.DataFrames.DataFrame[]
        """,
    )

    if options.include_setup
        write(
            io,
            """

                try
                    @info EegFun.section("Setup")
                    !isfile(config) && EegFun.@minimal_error "Config file does not exist: \$config"
                    cfg = EegFun.read_config(config)
                    isnothing(cfg) && EegFun.@minimal_error "Failed to load configuration from: \$config"

                    resolve_path(path::String) = isabspath(path) ? path : joinpath(base_dir, path)

                    pipeline_cfg = EegFun.PipelineConfig(cfg)
                    preprocess_cfg = pipeline_cfg.preprocess
                    files_cfg = pipeline_cfg.files

                    input_directory = resolve_path(files_cfg.input.directory)
                    !isdir(input_directory) && EegFun.@minimal_error "Input directory does not exist: \$input_directory"
                    raw_data_files = EegFun.get_files(input_directory, files_cfg.input.raw_data_files; recursive = files_cfg.input.recursive)
                    !EegFun.check_files_exist(raw_data_files) && EegFun.@minimal_error "Missing raw data files requested within TOML file!"
                    @info "Found \$(length(raw_data_files)) files: \$(join(raw_data_files, ", "))"

                    epoch_condition_file = resolve_path(files_cfg.input.epoch_condition_file)
                    !isfile(epoch_condition_file) && EegFun.@minimal_error "File missing: \$epoch_condition_file"
                    epoch_cfgs = EegFun.condition_parse_epoch(TOML.parsefile(epoch_condition_file))
                    @info "Epoch file: \$epoch_condition_file loaded"

                    layout_file = resolve_path(files_cfg.input.layout_file)
                    if !isfile(layout_file)
                        pkg_layout = EegFun.find_file(files_cfg.input.layout_file, joinpath(pkgdir(EegFun), "resources", "layouts"))
                        !isnothing(pkg_layout) && (layout_file = pkg_layout)
                    end
                    !isfile(layout_file) && EegFun.@minimal_error "Layout file not found: \$(files_cfg.input.layout_file)"
                    layout = EegFun.read_layout(layout_file)

                    output_directory = resolve_path(files_cfg.output.directory)
                    !isdir(output_directory) && mkpath(output_directory)

                    EegFun.print_config(cfg, joinpath(output_directory, "config.toml"))

                    EegFun.polar_to_cartesian_xy!(layout)
                    EegFun.polar_to_cartesian_xyz!(layout)
                    EegFun.get_neighbors_xy!(layout, preprocess_cfg.neighbor_criterion)
                    EegFun.print_layout_neighbors(layout, joinpath(output_directory, "neighbors.toml"))
            """,
        )
    else
        write(io, "\n    try\n")
    end

    write(
        io,
        """

                for data_file in raw_data_files
                    try
                        @info EegFun.section("Processing")
                        @info "File: \$data_file"
                        EegFun.setup_logging(joinpath(output_directory, "\$(EegFun.basename_without_ext(data_file)).log"); log_level = log_level)
        """,
    )

    for step_num = 1:options.num_steps
        println(io, "\n                @info EegFun.section(\"Step $step_num\")")
        for sub_num = 1:options.subsections_per_step
            println(io, "                @info EegFun.subsection(\"Step $step_num.$sub_num\")")
            println(io, "                # Your code here...")
            sub_num < options.subsections_per_step && println(io)
        end
    end

    write(
        io,
        """

                        @info EegFun.section("End of Processing")
                        @info "Successfully processed \$data_file"
                        processed_files += 1

                    catch e
                        @error "Error processing \$data_file: \$e"
                        push!(failed_files, data_file)
                    finally
                        EegFun.close_logging()
                    end
                end
        """,
    )

    if options.include_summary
        write(
            io,
            """

                    @info EegFun.section("Summary")
                    @info "\$processed_files success, \$(length(failed_files)) fail"
                    !isempty(failed_files) && @info "Failed files: \$(join(failed_files, ", "))"
            """,
        )
    end

    write(
        io,
        """

            catch e
                @error "Fatal error in preprocessing pipeline: \$e"
                rethrow(e)
            finally
                EegFun.close_global_logging()
            end
        end
        """,
    )

    if options.include_usage_example
        write(
            io,
            """

            # Usage: $function_name("your_config.toml"; log_level = :info)
            """,
        )
    end
end

"""
    generate_pipeline_template(output_file = "custom_pipeline.jl", function_name = "custom_preprocess"; options = PipelineTemplateOptions()) -> String

Generate a ready-to-customize EEG preprocessing pipeline script with setup, per-file logging, error handling, and summary boilerplate.
"""
function generate_pipeline_template(
    output_file::String = "custom_pipeline.jl",
    function_name::String = "custom_preprocess";
    options::PipelineTemplateOptions = PipelineTemplateOptions(),
)
    buf = IOBuffer(; sizehint = 4096)
    _write_pipeline_template(buf, function_name, options)
    write(output_file, take!(buf))

    @info "Pipeline template generated: $output_file"
    @info "Edit the template to add your custom processing steps"
    return output_file
end
